"""
The result of a Security Hub BatchUpdateFindings call.

BatchUpdateFindings does not raise for a finding it could not update; it lists it in UnprocessedFindings
with an ErrorCode. The codes are documented in the Security Hub API reference under
BatchUpdateFindingsUnprocessedFinding.
"""

from aws_utils.errors import AWSTransientError


class SecurityHubUpdateRejected(Exception):
    """Security Hub refused the update for a reason a retry will not change. Not retried."""


# Another update of the finding was in progress (Security Hub names BatchImportFindings running at the same
# time, as during a scan), or Security Hub failed internally.
RETRIED_CODES = frozenset({'ConcurrentUpdateError', 'InternalFailure'})


def check_batch_update(response):
    """Returns True if every finding was updated. A finding that no longer exists is logged and skipped,
    as there is nothing left to update. Raises AWSTransientError or SecurityHubUpdateRejected otherwise."""
    updated = True
    for finding in response.get('UnprocessedFindings', []):
        code = finding.get('ErrorCode')
        detail = f"{code}: {finding.get('ErrorMessage')} ({finding.get('FindingIdentifier', {}).get('Id')})"
        if code == 'FindingNotFound':
            print(f'WARNING: the finding no longer exists, nothing to update: {detail}')
            updated = False
        elif code in RETRIED_CODES:
            raise AWSTransientError(f'Security Hub did not update the finding: {detail}')
        else:
            raise SecurityHubUpdateRejected(f'Security Hub rejected the update: {detail}')
    return updated
